import os
import json
from typing import Any, Dict, List, Optional

from google.cloud import documentai


def _get_text(document: documentai.Document, text_anchor: Optional[documentai.Document.TextAnchor]) -> str:
    if not text_anchor or not text_anchor.text_segments:
        return ""
    parts: List[str] = []
    for segment in text_anchor.text_segments:
        start_index = int(segment.start_index) if segment.start_index is not None else 0
        end_index = int(segment.end_index) if segment.end_index is not None else 0
        parts.append(document.text[start_index:end_index])
    return "".join(parts).strip()


def _find_entity(entities: List[documentai.Document.Entity], type_names: List[str]) -> Optional[documentai.Document.Entity]:
    lowered = {t.lower() for t in type_names}
    for entity in entities:
        if entity.type_.lower() in lowered:
            return entity
    return None


def _collect_children(entity: documentai.Document.Entity) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    for child in entity.properties:
        key = child.type_.lower()
        value = child.normalized_value.text if child.normalized_value and child.normalized_value.text else child.mention_text
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value
    return result


def extract_invoice_fields(file_path: str, mime_type: str) -> Dict[str, Any]:
    project_id = os.environ["GOOGLE_CLOUD_PROJECT"]
    location = os.environ.get("DOCUMENTAI_LOCATION", "us")
    processor_id = os.environ["DOCUMENTAI_PROCESSOR_ID"]

    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"}
    )
    processor_name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as f:
        raw_document = documentai.RawDocument(content=f.read(), mime_type=mime_type)

    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    entities = list(document.entities)

    vendor_entity = _find_entity(entities, ["supplier_name", "vendor_name"])
    date_entity = _find_entity(entities, ["invoice_date"])
    total_entity = _find_entity(entities, ["total_amount", "invoice_total"])

    vendor = vendor_entity.normalized_value.text if vendor_entity and vendor_entity.normalized_value and vendor_entity.normalized_value.text else (vendor_entity.mention_text if vendor_entity else None)
    date = date_entity.normalized_value.text if date_entity and date_entity.normalized_value and date_entity.normalized_value.text else (date_entity.mention_text if date_entity else None)
    total = total_entity.normalized_value.text if total_entity and total_entity.normalized_value and total_entity.normalized_value.text else (total_entity.mention_text if total_entity else None)

    line_items: List[Dict[str, Any]] = []
    for entity in entities:
        if entity.type_.lower() == "line_item":
            item = _collect_children(entity)
            if not item and entity.mention_text:
                item = {"text": entity.mention_text}
            line_items.append(item)

    return {
        "provider": "google_document_ai",
        "processor": "Invoice Parser",
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw_entities": [
            {
                "type": e.type_,
                "mention_text": e.mention_text,
                "normalized_value": e.normalized_value.text if e.normalized_value and e.normalized_value.text else None,
                "confidence": e.confidence,
                "properties": [
                    {
                        "type": p.type_,
                        "mention_text": p.mention_text,
                        "normalized_value": p.normalized_value.text if p.normalized_value and p.normalized_value.text else None,
                        "confidence": p.confidence,
                    }
                    for p in e.properties
                ],
            }
            for e in entities
        ],
    }


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 3:
        raise SystemExit("Usage: python extract_invoice.py <file_path> <mime_type>")

    output = extract_invoice_fields(sys.argv[1], sys.argv[2])
    print(json.dumps(output, indent=2))
